1	/**
2	 * Ingestion orchestrator.
3	 *
4	 * Its only job is normalize-and-enqueue: turn raw Discord payloads (from either the
5	 * live gateway or the startup backfill) into the internal event shape and persist
6	 * them durably to the queue. It never calls JIRA — that separation is what lets the
7	 * queue guarantee at-least-once and survive restarts.
8	 *
9	 * discord.js-free and JIRA-free, so it is unit-testable with a fake gateway and the
10	 * in-memory queue.
11	 */
12	
13	import type { EventQueue } from '../db/index.js';
14	import { isResyncCommand, normalizeMessage, normalizeThreadCreated, toEnqueueInput } from './normalize.js';
15	import type { DiscordGateway, IngestedEvent, RawMessage, RawThread } from './types.js';
16	
17	/** Emitted when a user issues `!resync` in a forum channel (real-time only). */
18	export interface ResyncCommand {
19	  /** The forum channel the command was issued in (-> project key). */
20	  readonly channelName: string;
21	  /** Channel/thread id to post the summary reply into. */
22	  readonly replyChannelId: string;
23	  readonly requesterDisplayName: string;
24	}
25	
26	/** Minimal log surface; defaults to console. Kept injectable for tests. */
27	export interface IngestLogger {
28	  info(message: string, meta?: Record<string, unknown>): void;
29	  debug(message: string, meta?: Record<string, unknown>): void;
30	}
31	
32	const noopLogger: IngestLogger = {
33	  info: () => {},
34	  debug: () => {},
35	};
36	
37	export interface BackfillOptions {
38	  /** Lower time bound: only threads/messages at or after this instant are ingested. */
39	  readonly cutoff: Date;
40	  readonly includeArchived: boolean;
41	}
